{"content": "import sys

# Independent implementation of MISSION section 2 recurrence.
# Base convention: for q=0 the second branch reads f(-1,r) < 0; set f(-1,r)=0 so it
# does not fire; then f(0,0)=mex(empty)=1, and f(0,r)=f(0,0) for r>0 (first branch).
# We only compute the triangle r<=q; f(q,r)=f(q,q) for r>q.

Q = int(sys.argv[1]) if len(sys.argv) > 1 else 300

f = [[0]*(Q+1) for _ in range(Q+1)]

def mex(lst):
    st = set(lst)
    m = 1
    while m in st:
        m += 1
    return m

for q in range(Q+1):
    for r in range(0, q+1):
        if q == 0:
            f[q][r] = 1   # mex of empty set; r>q branch can't apply for r<=q=0 except r=0
        else:
            fq1r = f[q-1][r] if r <= q-1 else f[q-1][q-1]
            if fq1r < q:
                f[q][r] = fq1r
            else:
                s = []
                for a in range(q):
                    s.append(f[a][r] if r <= a else f[a][a])
                for b in range(r):
                    s.append(f[q][b])
                f[q][r] = mex(s)

# cross-check against solver table if given
if len(sys.argv) > 2:
    rows = []
    with open(sys.argv[2]) as fh:
        for line in fh:
            rows.append([int(x) for x in line.split()])
    bad = 0
    for q in range(Q+1):
        for r in range(Q+1):
            mine = f[q][r] if r <= q else f[q][q]
            if mine != rows[q][r]:
                bad += 1
                if bad < 10:
                    print("MISMATCH", q, r, mine, rows[q][r])
    print("cross-check against", sys.argv[2], "mismatches:", bad)

print("my table computed to Q =", Q)
print("diagonal d_n - n:", [(n, f[n][n]-n) for n in [1,2,3,4,5,10,50,100,min(500,Q),Q]])
", "path": "scratch_ref/mine.py"}

